SELECT q.* FROM question q
INNER JOIN section s ON q.section_id = s.id
WHERE s.course_id = #{courseId}

    AND q.question_type = #{questionType}

ORDER BY q.sort_order ASC, q.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1) FROM question q
INNER JOIN section s ON q.section_id = s.id
WHERE s.course_id = #{courseId}

    AND q.question_type = #{questionType}

SELECT * FROM question
WHERE section_id = #{sectionId}
ORDER BY sort_order ASC

SELECT * FROM question WHERE section_id IN
#{sectionId}
ORDER BY sort_order ASC

SELECT * FROM question
WHERE course_id = #{courseId}
ORDER BY sort_order ASC

SELECT * FROM question
WHERE course_id = #{courseId} and section_id = #{sectionId}

    AND test_batch_no = #{testBatchNo}

ORDER BY sort_order ASC

SELECT * FROM question
WHERE course_id = #{courseId}
AND question_category = #{questionCategory}

    AND test_batch_no = #{testBatchNo}

ORDER BY sort_order ASC

SELECT * FROM question
WHERE test_batch_no = #{testBatchNo}
ORDER BY sort_order ASC

SELECT q.* FROM question q
INNER JOIN (
    SELECT test_batch_no
    FROM question
    WHERE course_id = #{courseId}
    AND question_category = #{questionCategory}
    AND test_batch_no LIKE 'GEN_%'

        AND section_id = #{sectionId}

    ORDER BY create_time DESC
    LIMIT 1
) latest ON q.test_batch_no = latest.test_batch_no
ORDER BY q.sort_order ASC

